-- ============================================================

-- ID 980: Owner-Entity Transactions — Effect of Section 267 loss disallowance on related party sales
UPDATE questions SET
  stem = 'Hargrove owns 100% of Pinnacle Corp. He sells equipment with a basis of $85,000 and FMV of $55,000 to Pinnacle for $55,000, recognizing a $30,000 loss on his personal return. Separately, Hargrove''s wife sells land with a basis of $120,000 and FMV of $90,000 to Pinnacle for $90,000. How does Section 267 affect the loss recognition for each transaction, and why does the constructive ownership rule under Section 267(c) extend the disallowance to Hargrove''s wife?',
  choices = '["Hargrove''s $30,000 loss is disallowed under Section 267(a)(1) because he owns more than 50% of the corporation, and his wife''s $30,000 loss is also disallowed because Section 267(c)(2) attributes Hargrove''s 100% ownership to his spouse — both losses are permanently lost and provide no future tax benefit", "Hargrove''s $30,000 loss is disallowed but his wife''s $30,000 loss is allowed because she does not personally own any Pinnacle stock, and constructive ownership does not apply between spouses for Section 267 purposes", "Hargrove''s loss is disallowed under Section 267(a)(1), and his wife''s loss is also disallowed under constructive ownership — however, the losses are not permanently lost because when Pinnacle later sells the assets to unrelated parties, Pinnacle can use the disallowed losses to offset its recognized gains under Section 267(d)", "Both losses are allowed because Section 267 only applies to sales between an individual and a corporation where the individual owns more than 50% directly, not constructively"]'::jsonb,
  explanation = 'Correct (C): Under IRC Section 267(a)(1), losses are disallowed on sales between related parties, including a shareholder owning more than 50% of a corporation (Section 267(b)(2)). Hargrove directly owns 100%, so his $30,000 loss is disallowed. Under Section 267(c)(2), stock owned by an individual is constructively owned by the individual''s spouse — so Hargrove''s wife is treated as owning 100% of Pinnacle, making her $30,000 loss also disallowed. Critically, Section 267(d) provides a partial remedy: when the transferee (Pinnacle) later sells the property to an unrelated party at a gain, the gain is reduced (not below zero) by the previously disallowed loss. This means the disallowed losses are not permanently destroyed — they effectively shift to Pinnacle as a future gain reduction. (A) is wrong because the losses can provide future benefit under Section 267(d). (B) is wrong because constructive ownership explicitly applies between spouses. (D) is wrong because Section 267(c) applies constructive ownership rules to the 50% threshold.',
  correct_index = 2
WHERE id = 980;

-- ID 981: Owner-Entity Transactions — Analyzing Section 267(d) gain offset on subsequent sale
UPDATE questions SET
  stem = 'Continuing from a prior Section 267 transaction: Hargrove sold equipment (basis $85,000) to Pinnacle Corp for $55,000, and the $30,000 loss was disallowed under Section 267. Pinnacle''s basis in the equipment is $55,000 (the purchase price). Two years later, Pinnacle sells the equipment to an unrelated buyer for $100,000. How does Section 267(d) affect Pinnacle''s recognized gain, and what would the result be if Pinnacle sold the equipment for $60,000 instead?',
  choices = '["Pinnacle recognizes a $45,000 gain ($100,000 - $55,000) with no adjustment because Section 267(d) only benefits the original seller, not the purchasing corporation", "Pinnacle''s realized gain is $45,000 ($100,000 - $55,000 basis), but Section 267(d) allows a $30,000 offset from the previously disallowed loss, reducing recognized gain to $15,000 — if sold for $60,000 instead, the $5,000 realized gain is fully offset by the disallowed loss, producing $0 recognized gain, but the unused $25,000 of disallowed loss is permanently forfeited", "Pinnacle recognizes no gain on the $100,000 sale because Section 267(d) adjusts Pinnacle''s basis from $55,000 to $85,000 (reflecting the disallowed loss), and the $15,000 gain ($100,000 - $85,000) is treated as the original seller''s income", "Pinnacle recognizes the full $45,000 gain and Hargrove files an amended return to claim the $30,000 previously disallowed loss, resulting in a net $15,000 gain to the related party group"]'::jsonb,
  explanation = 'Correct (B): Under IRC Section 267(d), when property acquired in a Section 267 transaction is later sold to an unrelated party at a gain, the recognized gain is reduced (but not below zero) by the amount of the previously disallowed loss. Pinnacle''s realized gain on the $100,000 sale is $45,000 ($100,000 - $55,000 basis). The $30,000 disallowed loss offsets this gain, so Pinnacle recognizes only $15,000. If sold for $60,000, the realized gain of $5,000 is fully offset, producing $0 recognized gain — but the remaining $25,000 of unused disallowed loss is permanently lost because Section 267(d) cannot create a loss, only reduce a gain. This is a key analytical distinction: the disallowed loss can only be recovered to the extent of the transferee''s gain. (A) is wrong because Section 267(d) specifically benefits the transferee corporation. (C) is wrong because the mechanism is a gain reduction, not a basis adjustment. (D) is wrong because Hargrove cannot reclaim the loss — the benefit passes to Pinnacle through the gain offset.',
  correct_index = 1
WHERE id = 981;

